dx = ( GetBlur1(uv+vec2( 1.0 , 0.0 )*d)-GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
dz +=vec2(dx.y,dy.y);
vec3 bg = pow(length(dz)*0.8+0,0.7) + GetBlur2(uv).y*0.4-0.1;
ret = bg*vec3(0.4,0.5,0.7);
ret = mix(ret,vec3( 1.0 ,0.4, 0.0),GetPixel(clamp01(0.5 + (uv-0.5)+vec2(q19,q20)*vec2(-1, 1.0 ))).x);
//ret = mix(ret, 1.0 ,GetPixel(uv).z);
//ret = GetPixel(uv);
}
  fragColor = vec4(ret, 1.0);
}

